#!/bin/bash
# update-waf-ips.sh
# Generates nginx WAF IP allowlist configs for a given WAF provider and vhost.
#
# Usage:
#   update-waf-ips.sh PROVIDER VHOST
#
#   PROVIDER   wedos | sucuri
#   VHOST      virtual host name, e.g. fors.ch
#
# Output files (created under /home/sites/VHOST/conf/nginx/):
#   waf-ips.conf      geo block entries       (auto-generated)
#   waf-realip.conf   set_real_ip_from entries (auto-generated)
#
# Examples:
#   update-waf-ips.sh wedos  fors.ch
#   update-waf-ips.sh sucuri fors.ch
#
# Script location: /root/scripts/rsl/std-webserver-nginx/scripts/update-waf-ips.sh

set -euo pipefail

WEDOS_URL="https://ips.wedos.global/ips.txt"
MIN_IP_COUNT=5

SUCURI_IPS=(
    "192.88.134.0/23"
    "185.93.228.0/22"
    "66.248.200.0/22"
    "2a02:fe80::/29"
    "208.109.0.0/22"
)

# ── Helpers ───────────────────────────────────────────────────────────────────

log() { echo "[$(date '+%Y-%m-%d %H:%M:%S')] $*"; }
die() { log "ERROR: $*"; exit 1; }

usage() {
    echo "Usage: $(basename "$0") PROVIDER VHOST" >&2
    echo "" >&2
    echo "  PROVIDER   wedos | sucuri" >&2
    echo "  VHOST      virtual host name, e.g. fors.ch" >&2
    exit 1
}

# Writes geo and realip configs from a newline-separated IP list (stdin).
# Args: provider geo_conf realip_conf
write_configs() {
    local provider="$1" geo_conf="$2" realip_conf="$3"
    local timestamp
    timestamp="$(date -u '+%Y-%m-%d %H:%M:%S UTC')"

    local header
    header="# Auto-generated by update-waf-ips.sh on ${timestamp}
# Provider: ${provider}
# DO NOT EDIT MANUALLY"

    local ips=()
    while IFS= read -r line; do
        local ip="${line%%#*}"
        ip="${ip//[[:space:]]/}"
        [[ -n "$ip" ]] && ips+=("$ip")
    done

    local geo_tmp realip_tmp
    geo_tmp="$(mktemp --tmpdir="$(dirname "$geo_conf")")"
    realip_tmp="$(mktemp --tmpdir="$(dirname "$realip_conf")")"

    {
        echo "$header"
        for ip in "${ips[@]}"; do echo "    ${ip} 1;"; done
    } > "$geo_tmp"

    {
        echo "$header"
        for ip in "${ips[@]}"; do echo "set_real_ip_from ${ip};"; done
    } > "$realip_tmp"

    mv "$geo_tmp"    "$geo_conf"
    mv "$realip_tmp" "$realip_conf"
}

# ── Args ──────────────────────────────────────────────────────────────────────

[[ $# -eq 2 ]] || usage

PROVIDER="${1,,}"
VHOST="$2"

[[ "$PROVIDER" == "wedos" || "$PROVIDER" == "sucuri" ]] \
    || die "Unknown provider '${PROVIDER}'. Use 'wedos' or 'sucuri'."

WAF_DIR="/home/sites/${VHOST}/conf/nginx"
GEO_CONF="${WAF_DIR}/waf-ips.conf"
REALIP_CONF="${WAF_DIR}/waf-realips.conf"

mkdir -p "$WAF_DIR"

# ── Fetch or use static IPs ───────────────────────────────────────────────────

if [[ "$PROVIDER" == "wedos" ]]; then
    TMP_IPS="$(mktemp)"
    trap 'rm -f "$TMP_IPS"' EXIT

    log "Fetching Wedos WAF IPs from ${WEDOS_URL}"
    curl -sf --max-time 30 "$WEDOS_URL" -o "$TMP_IPS" \
        || die "Failed to fetch Wedos IPs — network error or URL changed"

    IP_COUNT="$(grep -cE '^[0-9a-fA-F:.]' "$TMP_IPS" || true)"
    (( IP_COUNT >= MIN_IP_COUNT )) \
        || die "Suspiciously few IPs fetched (${IP_COUNT}). Aborting to avoid locking out legitimate traffic."
    log "Fetched ${IP_COUNT} IP entries"

    write_configs "$PROVIDER" "$GEO_CONF" "$REALIP_CONF" < "$TMP_IPS"

else
    log "Using static Sucuri IPs (${#SUCURI_IPS[@]} entries)"
    printf '%s\n' "${SUCURI_IPS[@]}" | write_configs "$PROVIDER" "$GEO_CONF" "$REALIP_CONF"
fi

log "Written: ${GEO_CONF}"
log "Written: ${REALIP_CONF}"

# ── Test and reload nginx ─────────────────────────────────────────────────────

log "Testing nginx config..."
nginx -t 2>&1 || die "nginx config test failed. nginx was NOT reloaded."
log "Reloading nginx..."
nginx -s reload
log "Done — nginx reloaded with ${PROVIDER} WAF IPs"

